import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__device__ __forceinline__ double warp_reduce_sum(double val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffffu, val, offset);
    }
    return val;
}

// One block per row (per leading batch element). The normalized dimension D
// is large (64*256*256 = 4M elements), so each thread processes many elements
// with vectorized float4 loads. Mean and variance are computed in a single
// pass using double-precision accumulators (to avoid catastrophic
// cancellation given the large input mean), then the normalized output is
// written in a second fused pass: y = (x - mean) * rstd * w + b.
__global__ void layernorm_kernel(const float* __restrict__ x,
                                 const float* __restrict__ w,
                                 const float* __restrict__ b,
                                 float* __restrict__ y,
                                 int D, float eps) {
    const int row = blockIdx.x;
    const float* xr = x + (long)row * D;
    float* yr = y + (long)row * D;
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    const int lane = tid & 31;
    const int wid = tid >> 5;

    double lsum = 0.0;
    double lsq = 0.0;

    const int n4 = D >> 2;
    const float4* x4 = reinterpret_cast<const float4*>(xr);
    for (int i = tid; i < n4; i += nthreads) {
        float4 v = x4[i];
        lsum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        lsq += (double)v.x * v.x + (double)v.y * v.y +
               (double)v.z * v.z + (double)v.w * v.w;
    }
    for (int i = (n4 << 2) + tid; i < D; i += nthreads) {
        double v = (double)xr[i];
        lsum += v;
        lsq += v * v;
    }

    __shared__ double s_sum[32];
    __shared__ double s_sq[32];
    __shared__ double s_mean;
    __shared__ double s_rstd;

    double ws = warp_reduce_sum(lsum);
    double wq = warp_reduce_sum(lsq);
    if (lane == 0) {
        s_sum[wid] = ws;
        s_sq[wid] = wq;
    }
    __syncthreads();

    if (wid == 0) {
        const int nwarps = nthreads >> 5;
        double a = (lane < nwarps) ? s_sum[lane] : 0.0;
        double c = (lane < nwarps) ? s_sq[lane] : 0.0;
        a = warp_reduce_sum(a);
        c = warp_reduce_sum(c);
        if (lane == 0) {
            double mean = a / (double)D;
            double var = c / (double)D - mean * mean;
            s_mean = mean;
            s_rstd = rsqrt(var + (double)eps);
        }
    }
    __syncthreads();

    const float fm = (float)s_mean;
    const float fr = (float)s_rstd;

    const float4* w4 = reinterpret_cast<const float4*>(w);
    const float4* b4 = reinterpret_cast<const float4*>(b);
    float4* y4 = reinterpret_cast<float4*>(yr);

    for (int i = tid; i < n4; i += nthreads) {
        float4 v = x4[i];
        float4 ww = w4[i];
        float4 bb = b4[i];
        float4 o;
        o.x = (v.x - fm) * fr * ww.x + bb.x;
        o.y = (v.y - fm) * fr * ww.y + bb.y;
        o.z = (v.z - fm) * fr * ww.z + bb.z;
        o.w = (v.w - fm) * fr * ww.w + bb.w;
        y4[i] = o;
    }
    for (int i = (n4 << 2) + tid; i < D; i += nthreads) {
        yr[i] = (xr[i] - fm) * fr * w[i] + b[i];
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w,
                                torch::Tensor b, double eps) {
    auto y = torch::empty_like(x);
    const int64_t D = w.numel();
    const int64_t B = x.numel() / D;
    if (B == 0 || D == 0) return y;
    const int threads = 1024;
    layernorm_kernel<<<(int)B, threads>>>(
        x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(),
        y.data_ptr<float>(), (int)D, (float)eps);
    return y;
}
"""

cpp_src = "torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b, double eps);"

_ln_mod = load_inline(
    name="layernorm_fused_cuda",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single fused custom CUDA kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ln_mod.layernorm_forward(
            x.contiguous(), self.weight.contiguous(), self.bias.contiguous(), self.eps
        )

